import sys
import numpy as np
from rdkit import Chem
m0=Chem.MolFromMolFile('initial.mol',removeHs=False)
for f in sys.argv[1:]:
 m=Chem.Mol(m0)
 x=Chem.MolFromXYZFile(f).GetConformer().GetPositions()
 c=m.GetConformer()
 for i,p in enumerate(x): c.SetAtomPosition(i,p)
 Chem.AssignAtomChiralTagsFromStructure(m,replaceExistingTags=True)
 Chem.AssignStereochemistry(m,cleanIt=True,force=True)
 print('\nFILE',f,'STEREO',Chem.FindMolChiralCenters(m,includeUnassigned=True))
 for j in [0,22,25,26]: print('Pd dist',j+1,np.linalg.norm(x[j]-x[21]))
 for a,b,c in [(21,26,27),(0,21,25),(22,21,26),(0,21,26)]:
  p=x[a]-x[b];q=x[c]-x[b];print('Angle',a+1,b+1,c+1,np.degrees(np.arccos(np.clip(np.dot(p,q)/np.linalg.norm(p)/np.linalg.norm(q),-1,1))))
 for b in m.GetBonds():
  i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx()
  if 21 in (i,j):continue
  d=np.linalg.norm(x[i]-x[j])
  if d>1.65 or d<0.9: print('ODD bond',i,j,d)
 for i in range(len(x)):
  for j in range(i):
   if m.GetBondBetweenAtoms(i,j):continue
   if np.linalg.norm(x[i]-x[j])<1.5:print('CLOSE',i,j,np.linalg.norm(x[i]-x[j]))
